"""matplotlib._mathtext — TeX-style math parsing stub.

Real matplotlib parses $\alpha + \beta$ into a tree of Glyph / Hbox /
Vbox primitives, then renders via FT2Font. The plotly backend doesn't
have any of that; raw `$...$` strings come through to plotly labels
which renders them via MathJax (LaTeX-aware) — so user math actually
works for free, just not via this code path.

This module exists so `import matplotlib._mathtext` doesn't fail.
"""


class Parser:
    """Math expression parser. The real upstream parser builds a tree
    of layout primitives; we return a single ``Hlist`` whose children
    are one ``Char`` per non-math character of ``s`` (stripped of the
    leading/trailing ``$``).

    This means callers that walk the result (``for c in parser.parse(s).children``)
    see real nodes instead of None — enough for layout/extent estimation.
    Actual glyph rendering still goes through plotly's MathJax for
    correct LaTeX layout.
    """

    def __init__(self):
        pass

    def parse(self, s, fonts_object=None, fontsize=12, dpi=72):
        if not s:
            return Hlist([])
        # Strip surrounding $...$.
        text = s
        if text.startswith('$') and text.endswith('$'):
            text = text[1:-1]
        children = []
        # Estimate per-character width as 0.6 em at the requested size.
        char_w = float(fontsize) * 0.6
        for ch in text:
            node = Char(ch)
            node.size = float(fontsize)
            node.width = char_w
            node.height = float(fontsize) * 0.7
            node.depth = float(fontsize) * 0.2
            children.append(node)
        box = Hlist(children)
        box.width = char_w * len(children)
        box.height = float(fontsize) * 0.7
        box.depth = float(fontsize) * 0.2
        return box


class MathTextWarning(UserWarning): pass


class Glyph:
    def __init__(self, *a, **k): pass


class Hbox:
    def __init__(self, *a, **k): pass


class Vbox:
    def __init__(self, *a, **k): pass


def get_unicode_index(symbol, math=True): return ord(symbol[0]) if symbol else 0


# ─── Added: missing public classes from upstream _mathtext.py ──────


class Node:
    """Base of the mathtext layout tree. Subclasses (Char, Box, Hbox,
    Vbox, …) carry positioning information used by the renderer.
    Plotly's MathJax does all the actual layout, so these are
    placeholders that satisfy isinstance checks and minimal
    introspection."""

    def __init__(self):
        self.width = 0.0
        self.height = 0.0
        self.depth = 0.0
        self.size = 12.0

    def shrink(self):    pass
    def grow(self):      pass
    def render(self, *a, **kw): pass


class Box(Node):
    def __init__(self, width=0, height=0, depth=0):
        super().__init__()
        self.width, self.height, self.depth = width, height, depth


class Char(Node):
    """A single character node — the leaf of the layout tree."""
    def __init__(self, c, state=None):
        super().__init__()
        self.c = c
        self.state = state


class Accent(Char):
    """A character drawn with an accent over the top (e.g. \\hat x)."""
    pass


class AutoHeightChar(Char):
    """A delimiter whose height/depth grows to fit its contents."""
    def __init__(self, c, height=0, depth=0, state=None):
        super().__init__(c, state)
        self.height, self.depth = height, depth


class AutoWidthChar(Char):
    """A character whose width grows (e.g. extensible arrows)."""
    def __init__(self, c, width=0, state=None):
        super().__init__(c, state)
        self.width = width


class List(Box):
    """A horizontal or vertical list of child nodes."""
    def __init__(self, elements):
        super().__init__()
        self.children = list(elements)


class Hlist(List):
    """Horizontal list — children stacked left-to-right."""
    pass


class Vlist(List):
    """Vertical list — children stacked top-to-bottom."""
    pass


class Rule(Box):
    """A solid filled rectangle — fraction bars, table borders, etc."""
    def __init__(self, width, height, depth, state=None):
        super().__init__(width, height, depth)
        self.state = state


class Hrule(Rule):
    """Horizontal rule."""
    def __init__(self, state=None, thickness=None):
        super().__init__(1.0, thickness or 0.05, 0, state)


class Vrule(Rule):
    """Vertical rule."""
    def __init__(self, state=None):
        super().__init__(0.05, 1.0, 0, state)


class Glue(Node):
    """Stretchable spacing between nodes (TeX's glue concept)."""
    SPACE_FACTORS = {'fil': 0, 'fill': 1, 'filll': 2,
                     'neg_fil': 0, 'neg_fill': 1, 'neg_filll': 2,
                     'empty': 0, 'ss': 0}

    def __init__(self, glue_type='ss'):
        super().__init__()
        self.glue_type = glue_type


class HCentered(Hlist):
    """Hlist that centers its contents horizontally."""
    pass


class VCentered(Vlist):
    """Vlist that centers its contents vertically."""
    pass


class Kern(Node):
    """Fixed horizontal spacing."""
    def __init__(self, width=0):
        super().__init__()
        self.width = width


class SubSuperCluster(Hlist):
    """Subscript / superscript cluster attached to a base node."""
    pass


class Ship:
    """Iterator that walks a Node tree and emits draw commands. The
    shim's version doesn't actually render anything — it traverses for
    side-effect compatibility."""

    def __init__(self):
        self.cur_s = 0
        self.cur_v = 0
        self.cur_h = 0

    def __call__(self, box, ox=0, oy=0):
        # Walk the tree without rendering anything.
        for child in getattr(box, 'children', ()):
            if hasattr(child, 'children'):
                self(child)


# Re-export ship instance — upstream calls it directly as `ship(box)`.
ship = Ship()


# ── Font / character helpers ──────────────────────────────────────


class Fonts:
    """Base font class — provides character-metric queries for the
    rendering pipeline. The shim returns zeros for everything."""

    def __init__(self, default_font_prop=None, mathtext_backend=None):
        self.default_font_prop = default_font_prop

    def get_kern(self, font1, fontclass1, sym1, fontsize1,
                 font2, fontclass2, sym2, fontsize2, dpi):
        return 0.0

    def get_metrics(self, font, font_class, sym, fontsize, dpi, math=True):
        class _M:
            advance = 0; height = 0; width = 0; xmin = 0; xmax = 0; ymin = 0; ymax = 0; iceberg = 0; slanted = False
        return _M()

    def get_xheight(self, font, fontsize, dpi):
        return 0.0

    def get_underline_thickness(self, font, fontsize, dpi):
        return 0.5

    def render_glyph(self, ox, oy, font, font_class, sym, fontsize, dpi):
        pass

    def render_rect_filled(self, x1, y1, x2, y2):
        pass


class TruetypeFonts(Fonts):
    """Font lookup against TrueType files — stubbed since the plotly
    backend doesn't render glyphs itself."""
    pass


class BakomaFonts(TruetypeFonts):
    """TeX Bakoma font set."""
    pass


class UnicodeFonts(TruetypeFonts):
    """Generic Unicode font set."""
    pass


class DejaVuFonts(UnicodeFonts):
    """DejaVu Sans/Serif font set — matplotlib's default."""
    pass


class DejaVuSerifFonts(DejaVuFonts):
    pass


class DejaVuSansFonts(DejaVuFonts):
    pass


class StixFonts(UnicodeFonts):
    """STIX font set — used for ``rcParams['mathtext.fontset'] = 'stix'``."""
    pass


class StixSansFonts(StixFonts):
    pass


# ── Font-spacing constant tables ──────────────────────────────────


class FontConstantsBase:
    """Per-font metric constants used by the layout engine. The shim
    exposes the same dataclass-style attributes upstream uses; values
    are taken from upstream's defaults."""
    script_space     = 0.05
    subdrop          = 0.4
    sub1             = 0.2
    sub2             = 0.3
    sup1             = 0.5
    delta            = 0.025
    delta_slanted    = 0.2
    delta_integral   = 0.1


class ComputerModernFontConstants(FontConstantsBase):
    script_space = 0.075
    subdrop      = 0.2
    sub1         = 0.2
    sub2         = 0.3
    sup1         = 0.45


class STIXFontConstants(FontConstantsBase):
    script_space = 0.1
    sub1         = 0.25
    sub2         = 0.3
    sup1         = 0.55
    delta        = 0.05


class STIXSansFontConstants(STIXFontConstants):
    pass


class DejaVuSerifFontConstants(FontConstantsBase):
    pass


class DejaVuSansFontConstants(FontConstantsBase):
    pass


# Lookup table mapping font set name → constants class.
_font_constant_mapping = {
    'cm':           ComputerModernFontConstants,
    'stix':         STIXFontConstants,
    'stixsans':     STIXSansFontConstants,
    'dejavuserif':  DejaVuSerifFontConstants,
    'dejavusans':   DejaVuSansFontConstants,
}


# ── Parse-tree node aliases used by tests/docs ────────────────────


class NegativeSpace(Glue):
    """Backwards spacing — used by TeX's ``\\!``, ``\\,``, etc."""
    pass


class Error(Exception):
    """A parse error in mathtext input."""
    pass


# Parser internals exposed via a module-level alias.
class MathTextParser(Parser):
    """Public alias of :class:`Parser` — matches the name some
    upstream callers import."""

    def parse(self, s, dpi=72, prop=None):
        return None


class StandardPsFonts(Fonts):
    """PostScript-standard font set (Helvetica, Courier, Times)."""
    pass


# ── Geometry helpers used by the parser ──────────────────────────


def get_unicode_codepoint(sym, math=True):
    """Alias of :func:`get_unicode_index` — some upstream code uses
    the longer name."""
    return get_unicode_index(sym, math)


# ─── Added: remaining public names from upstream _mathtext.py ──────


from collections import namedtuple


# Levels of script-size shrink (script, scriptscript) and the factor
# applied at each level. Used by the layout engine to size subscripts.
NUM_SIZE_LEVELS = 6
SHRINK_FACTOR = 0.7


# Per-glyph metadata namedtuples used by the layout pipeline.
FontInfo = namedtuple('FontInfo', ['font', 'fontsize', 'postscript_name',
                                    'metrics', 'symbol_name', 'num',
                                    'glyph', 'offset'])
FontMetrics = namedtuple('FontMetrics', ['advance', 'height', 'width',
                                          'xmin', 'xmax', 'ymin', 'ymax',
                                          'iceberg', 'slanted'])


class ParserState:
    """State tracked by the parser as it consumes a math expression —
    current font, fontsize, dpi, and the stack of grouping contexts."""

    def __init__(self, font=None, font_class=None, fontsize=12, dpi=72):
        self.font = font
        self.font_class = font_class
        self.fontsize = fontsize
        self.dpi = dpi

    def copy(self):
        return ParserState(self.font, self.font_class, self.fontsize, self.dpi)


class Output:
    """Result of parsing a mathtext expression — a tree of nodes plus
    the bounding box and a list of glyph/rect commands. Used as the
    return value of :meth:`Parser.parse`."""

    def __init__(self, box=None, width=0, height=0, depth=0):
        self.box = box
        self.width = width
        self.height = height
        self.depth = depth
        self.glyphs = []
        self.rects = []

    def to_vector(self):       return VectorParse(self)
    def to_raster(self, dpi=72): return RasterParse(self, dpi)


class VectorParse:
    """Vector-format render of an :class:`Output`. Holds the size and
    the lists of glyphs/rects ready for emission to a vector backend
    (SVG/PDF/PGF)."""

    def __init__(self, output=None):
        self.width = getattr(output, 'width', 0)
        self.height = getattr(output, 'height', 0)
        self.depth = getattr(output, 'depth', 0)
        self.glyphs = getattr(output, 'glyphs', [])
        self.rects = getattr(output, 'rects', [])


class RasterParse:
    """Raster-format render of an :class:`Output` — an RGBA array at
    the requested ``dpi``. The shim returns a zero array."""

    def __init__(self, output=None, dpi=72):
        import numpy as _np
        w = max(1, int(getattr(output, 'width', 0) * dpi / 72))
        h = max(1, int(getattr(output, 'height', 0) * dpi / 72))
        self.image = _np.zeros((h, w, 4), dtype=_np.uint8)
        self.width = w
        self.height = h
        self.depth = getattr(output, 'depth', 0)
        self.ox = 0
        self.oy = 0


def cmd(s):
    """Decorator used by upstream's pyparsing grammar to register a
    handler for a parser command. The shim doesn't use pyparsing, so
    this is a passthrough."""
    if callable(s):
        return s
    return lambda fn: fn
